referenceSolutions.javascript:
export function asteroidCollision(asteroids          )           {
const s         =[];for(const x of asteroids){let alive=true;while(alive&&x<0&&s.length&&s[s.length-1]>0){const y=s[s.length-1];if(y< -x)s.pop();else {if(y===-x)s.pop();alive=false;}}if(alive)s.push(x);}return s;
}

